import sys

def count_segments(s):
    count = 0
    in_segment = False
    for c in s:
        if c == '*':
            if not in_segment:
                count += 1
                in_segment = True
        else:
            in_segment = False
    return count

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    a = []
    for _ in range(n):
        a.append(int(next(iterator)))

    b = []
    for _ in range(m):
        b.append(int(next(iterator)))

    grid = [['.' for _ in range(m)] for _ in range(n)]

    def get_row_segments(r):
        return count_segments("".join(grid[r]))

    def get_col_segments(c):
        col_str = "".join(grid[r][c] for r in range(n))
        return count_segments(col_str)

    def is_valid():
        for r in range(n):
            if get_row_segments(r) != a[r]:
                return False
        for c in range(m):
            if get_col_segments(c) != b[c]:
                return False
        return True

    def can_place(r, c, val):
        grid[r][c] = val
        row_ok = get_row_segments(r) <= a[r]
        col_ok = get_col_segments(c) <= b[c]
        if not row_ok or not col_ok:
            grid[r][c] = '.'
            return False

        if val == '.':
            if get_row_segments(r) > a[r]:
                grid[r][c] = '.'
                return False
            if get_col_segments(c) > b[c]:
                grid[r][c] = '.'
                return False

        return True

    def backtrack(idx):
        if idx == n * m:
            return is_valid()

        r, c = divmod(idx, m)

        for val in ['*', '.']:
            if can_place(r, c, val):
                if backtrack(idx + 1):
                    return True
                grid[r][c] = '.'

        return False

    backtrack(0)

    for row in grid:
        print("".join(row))

if __name__ == "__main__":
    solve()
